void handle_vm_cmdRequestDecomposeCard(GameClient& cl, const uint8_t* body, size_t len)
{
    if (len < 1) return;
    uint8_t n = body[0];
    if (1 + n > len) return;
    applyLpc("cmd_request_decompose_card", {make_int(cl.clientNo), make_string(body + 1, n)});
}

